### Wrapper obrigatório para componentes com React Query
```typescript
// src/features/estoque/ui/EstoqueCard.test.tsx
import { render, screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { EstoqueCard } from './EstoqueCard'

// ✅ Wrapper padrão — usar em todo teste com useQuery/useMutation
function renderWithProviders(ui: React.ReactElement) {
  const queryClient = new QueryClient({
    defaultOptions: {
      queries: { retry: false, gcTime: 0 },
      mutations: { retry: false }
    }
  })
  return {
    ...render(<QueryClientProvider client={queryClient}>{ui}</QueryClientProvider>),
    queryClient
  }
}

describe('EstoqueCard', () => {
  it('exibe quantidade formatada', async () => {
    const { getByText } = renderWithProviders(
      <EstoqueCard quantidade={42} produto="Brownie" />
    )
    expect(getByText('42')).toBeInTheDocument()
  })

  it('estado de loading', () => {
    const { getByTestId } = renderWithProviders(<EstoqueCard isLoading />)
    expect(getByTestId('skeleton')).toBeInTheDocument()
  })
})
```

